ON DUPLICATE KEY 
UPDATE 
    -- if the existing value and new value DO NOT equal eachother
        -- return the "new" inserted values "value"
        -- else current column "value"
    `subid` = IF(`subid` <> VALUES(`subid`), VALUES(`subid`), `subid`),
    `name` = IF(`name` <> VALUES(`name`), VALUES(`name`), `name`),
    `sortname` = IF(`sortname` <> VALUES(`sortname`), VALUES(`sortname`), `sortname`),
    `type` = IF(`type` <> VALUES(`type`), VALUES(`type`), `type`),
    `stackSize` = IF(`stackSize` <> VALUES(`stackSize`), VALUES(`stackSize`), `stackSize`),
    `flags` = IF(`flags` <> VALUES(`flags`), VALUES(`flags`), `flags`),
    `aH` = IF(`aH` <> VALUES(`aH`), VALUES(`aH`), `aH`),
    `BaseSell` = IF(`BaseSell` <> VALUES(`BaseSell`), VALUES(`BaseSell`), `BaseSell`)
;

